exports.main = async (event, callback) => {

  const dataNascimento = event.inputFields.data_de_nascimento;

  function calcularIdade(data) {
    const hoje = new Date();
    const nascimento = new Date(data);

    let idade = hoje.getFullYear() - nascimento.getFullYear();
    const m = hoje.getMonth() - nascimento.getMonth();

    if (m < 0 || (m === 0 && hoje.getDate() < nascimento.getDate())) {
      idade--;
    }

    return idade;
  }

  function classificarIdade(idade) {
    if (idade <= 29) return "Até 29 anos";
    if (idade <= 34) return "30 a 34 anos";
    if (idade <= 39) return "35 a 39 anos";
    if (idade <= 44) return "40 a 44 anos";
    return "Acima de 45 anos";
  }

  const idade = calcularIdade(dataNascimento);
  const faixa = classificarIdade(idade);

  callback({
    outputFields: {
      qual_sua_idade: faixa
    }
  });

};

